export const byStatus = (s: ProjectStatus) => projects.filter((p) => p.status === s);
export const bySlug = (slug: string) => projects.find((p) => p.slug === slug);

export const areas = [...new Set(projects.map((p) => p.area))].sort();

export const stats = {
  total: projects.length,
  ongoing: byStatus("ongoing").length,
  handedOver: byStatus("handed-over").length,
  upcoming: byStatus("upcoming").length,
  apartments: projects.reduce((n, p) => n + p.apartments, 0),
  areas: areas.length,
  since: 2012,
};
